import {execFileSync} from 'node:child_process';
import {appendFileSync} from 'node:fs';
const out=process.env.NIGHT_ARTIFACTS;
globalThis.__nightLoad=(label)=>appendFileSync(out+'/loads.jsonl',JSON.stringify({at:new Date().toISOString(),pid:process.pid,label,uptime:execFileSync('/usr/bin/uptime',{encoding:'utf8'}).trim()})+'\n');
globalThis.__nightSamples=(key,samples)=>appendFileSync(out+'/render-samples.jsonl',JSON.stringify({key,samples})+'\n');
const listen=net.Server.prototype.listen;
let port=4450;
net.Server.prototype.listen=function(...args){
 if(typeof args[0]==='number'){if(args[0]!==0&&(args[0]<4450||args[0]>4459))throw Error('Port outside lane');if(args[0]===0)args[0]=port++;}
 else if(args[0]&&typeof args[0]==='object'&&'port' in args[0]){if(!args[0].port)args[0]={...args[0],port:port++};else if(args[0].port<4450||args[0].port>4459)throw Error('Port outside lane');}
 if(port>4460)throw Error('Port budget exhausted');
 return listen.apply(this,args);
};
registerHooks({load(url,context,next){const r=next(url,context);if(typeof r.source!=='string'&&!Buffer.isBuffer(r.source))return r;let s=r.source.toString();
 if(url.endsWith('/apps/resume-bench/run.ts'))s=s.replace('const result = await measure(', 'globalThis.__nightLoad({suite:"resume",condition,scenario,lane,repeat:r}); const result = await measure(');
 if(url.endsWith('/apps/dom-bench/render/krausest.ts'))s=s.replace('samples[lane]!.push(await iteration(', 'globalThis.__nightLoad({suite:"render",bench:bench.id,rate,lane,repeat:i}); samples[lane]!.push(await iteration(').replace('results[key] = {};','globalThis.__nightSamples(key,samples); results[key] = {};');
 if(url.endsWith('/apps/dom-bench/run.ts'))s=s.replace('trials.push(await trial(framework, rows, repeat));','globalThis.__nightLoad({suite:"dom",framework,rows,repeat}); trials.push(await trial(framework, rows, repeat));');
 if(url.endsWith('/apps/dom-bench/krausest/run.ts'))s=s.replaceAll('const { page, errors } = await newPage(browser);','globalThis.__nightLoad({suite:"krausest",url,bench:typeof bench!=="undefined"?bench.id:"startup"}); const { page, errors } = await newPage(browser);');
 return {...r,source:s};}});
