import subprocess,os,sys,time,json,signal,pathlib
out=pathlib.Path(__file__).resolve().parent
label=sys.argv[1]; args=sys.argv[2:]
if label in ['dom-peers','dom-large','profile-resume']: args=[args[0],str(out/'locked.mjs')]+args[1:]
env=os.environ.copy();env['NIGHT_ARTIFACTS']=str(out);env['NODE_OPTIONS']='--max-old-space-size=1536 --import='+str(out/'preload.mjs')
with open(out/(label+'.log'),'w') as log:
 p=subprocess.Popen(['nice','-n','10']+args,stdout=log,stderr=subprocess.STDOUT,env=env,start_new_session=True)
 peak=0; exceeded=False
 while p.poll() is None:
  lines=subprocess.check_output(['ps','-axo','pid=,ppid=,rss='],text=True).splitlines(); procs=[list(map(int,l.split())) for l in lines if len(l.split())==3]; ids={p.pid}
  for _ in range(12):
   ids|={pid for pid,ppid,rss in procs if ppid in ids}
  rss=sum(rss for pid,ppid,rss in procs if pid in ids);peak=max(peak,rss)
  if rss>2800*1024:
   exceeded=True;os.killpg(p.pid,signal.SIGTERM)
  time.sleep(.25)
 result={'label':label,'command':args,'exit':p.returncode,'peakTreeKiB':peak,'guardKilled':exceeded}
 (out/(label+'-guard.json')).write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result));sys.exit(p.returncode or int(exceeded))

