import {readFileSync,writeFileSync,readdirSync} from 'node:fs';
import {gunzipSync} from 'node:zlib';
import {resolve} from 'node:path';
import {phases,mainThread} from '../../../apps/dom-bench/render/phases.ts';
const root=resolve('apps/resume-bench/results');
const name=readdirSync(root).filter(x=>/^2026-10-28.*\.json$/.test(x)).find(x=>JSON.parse(readFileSync(resolve(root,x))).lanes.length===5);
const data=JSON.parse(readFileSync(resolve(root,name)));
const out=[];
for(const r of data.runs){
 const path=resolve(root,data.traces,r.condition,r.scenario,`${r.lane}-r${r.repeat}.json.gz`);
 const trace=JSON.parse(gunzipSync(readFileSync(path))).traceEvents;
 const input=trace.find(e=>e.name==='EventDispatch'&&['pointerdown','keydown','touchstart'].includes(e.args?.data?.type));
 const parse=trace.find(e=>e.name==='ParseHTML');
 const base=input??parse;if(!base)continue;
 const tid=mainThread(trace,base.pid);
 const first=trace.filter(e=>e.pid===base.pid&&e.tid===tid).reduce((a,e)=>Math.min(a,e.ts),Infinity);
 const end=input?.ts??Math.max(...trace.filter(e=>e.pid===base.pid&&e.tid===tid).map(e=>e.ts+(e.dur??0)));
 const byName={};const before=phases(trace,base.pid,tid,first,end,byName);
 const events=trace.filter(e=>e.pid===base.pid&&e.tid===tid&&e.name==='EventDispatch'&&['input','click','keydown'].includes(e.args?.data?.type)).map(e=>({type:e.args.data.type,ms:(e.dur??0)/1000}));
 out.push({condition:r.condition,scenario:r.scenario,lane:r.lane,repeat:r.repeat,beforeInput:before,beforeByName:byName,events});
}
writeFileSync('.artifacts/night/2026-10-28-7820b7579/trace-summary.json',JSON.stringify(out,null,2)+'\n');

