import {chromium} from 'playwright';
import {serve} from '../../../apps/resume-bench/serve.ts';
import {mkdirSync,writeFileSync} from 'node:fs';
import {resolve} from 'node:path';
const out=resolve('.artifacts/night/2026-10-28-7820b7579/profiles');mkdirSync(out,{recursive:true});
const allLanes=['rivet','solid-stable','qwik-stable','qwik'];const servers={};for(const lane of allLanes)servers[lane]=await serve(resolve('apps/resume-bench/dist',lane));
const browser=await chromium.launch({channel:'chrome',headless:true,args:['--use-mock-keychain','--password-store=basic']});
const summaries=[];
try{
 for(const scenario of ['hoverClick','filterKey','navigate'])for(let repeat=0;repeat<3;repeat++)for(let k=0;k<2;k++){
 const lanes=['rivet',scenario==='hoverClick'?'qwik':scenario==='filterKey'?'solid-stable':'qwik-stable'];const lane=lanes[(k+repeat)%lanes.length];globalThis.__nightLoad({suite:'profile',scenario,lane,repeat});
 const context=await browser.newContext({viewport:{width:1280,height:800}});const page=await context.newPage();
 try{
 const cdp=await context.newCDPSession(page);await cdp.send('Network.enable');await cdp.send('Network.setCacheDisabled',{cacheDisabled:true});
 await cdp.send('Network.emulateNetworkConditions',{offline:false,latency:150,downloadThroughput:1.6*1024*1024/8,uploadThroughput:750*1024/8});
 await cdp.send('Emulation.setCPUThrottlingRate',{rate:4});
 await page.goto(servers[lane].url,{waitUntil:'load'});await page.waitForTimeout(1000);
 if(scenario==='hoverClick'){await page.hover('#inc');await page.waitForTimeout(600);}if(scenario==='keyClick')await page.focus('#inc');if(scenario==='filterKey')await page.click('#filter');
 await cdp.send('Profiler.enable');await cdp.send('Profiler.setSamplingInterval',{interval:100});await cdp.send('Profiler.start');
 if(scenario==='hoverClick'){await page.mouse.down();await page.mouse.up();await page.waitForFunction(()=>document.querySelector('#count').textContent==='1');}
 if(scenario==='keyClick'){await page.keyboard.press('Enter');await page.waitForFunction(()=>document.querySelector('#count').textContent==='1');}
 if(scenario==='filterKey'){await page.keyboard.type('g');await page.waitForFunction(()=>document.querySelectorAll('#rows li').length===100);}
 if(scenario==='navigate'){await page.click('#rows li:nth-child(3) a.open');await page.waitForSelector('#detail');}
 const {profile}=await cdp.send('Profiler.stop');const name=`${scenario}-${lane}-${repeat}`;writeFileSync(resolve(out,name+'.cpuprofile'),JSON.stringify(profile));
 const nodes=new Map(profile.nodes.map(n=>[n.id,n]));const self=new Map();for(let i=0;i<(profile.samples??[]).length;i++){const node=nodes.get(profile.samples[i]);const c=node.callFrame;const key=JSON.stringify({name:c.functionName,url:c.url,line:c.lineNumber,column:c.columnNumber});self.set(key,(self.get(key)??0)+(profile.timeDeltas[i]??0)/1000);}
 const sites=[...self].map(([key,ms])=>({...JSON.parse(key),ms})).sort((a,b)=>b.ms-a.ms);summaries.push({scenario,lane,repeat,sites});console.log(name,sites.slice(0,8));
 }finally{await context.close();}
 }
}finally{await browser.close();for(const s of Object.values(servers))await s.close();}
writeFileSync(resolve(out,'summary.json'),JSON.stringify(summaries,null,2)+'\n');

