import {readFileSync,readdirSync,writeFileSync} from 'node:fs';
import {resolve,relative} from 'node:path';
import {brotliCompressSync,gzipSync,constants} from 'node:zlib';
const root=resolve('apps/resume-bench/dist');
const sizes=(b)=>({raw:Buffer.byteLength(b),brotli:brotliCompressSync(b,{params:{[constants.BROTLI_PARAM_QUALITY]:11}}).length,gzip:gzipSync(b).length});
const walk=(d)=>readdirSync(d,{withFileTypes:true}).flatMap(f=>f.isDirectory()?walk(resolve(d,f.name)):[resolve(d,f.name)]);
const result={};
for(const lane of ['rivet','solid-stable','solid','qwik-stable','qwik']){
 const dir=resolve(root,lane);const html=readFileSync(resolve(dir,'index.html'),'utf8');
 const scripts=[...html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script>/g)].map(m=>({attributes:m[1],...sizes(Buffer.from(m[2]))}));
 const comments=[...html.matchAll(/<!--[\s\S]*?-->/g)].map(m=>m[0]);
 result[lane]={html:sizes(Buffer.from(html)),scripts,comments:{count:comments.length,raw:comments.join('').length},assets:walk(dir).filter(f=>/\.m?js$/.test(f)).map(f=>({path:relative(dir,f),...sizes(readFileSync(f))})).sort((a,b)=>b.brotli-a.brotli)};
}
writeFileSync('.artifacts/night/2026-10-28-7820b7579/bytes.json',JSON.stringify(result,null,2)+'\n');
